export default [{"id":"2596","jozz":"17","page":"332","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"3","line_end":"3","aya_no":"1","aya_text":"يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡۚ إِنَّ زَلۡزَلَةَ ٱلسَّاعَةِ شَيۡءٌ عَظِيمٞ","aya_text_emlaey":"ياأيها الناس اتقوا ربكم إن زلزلة الساعة شيء عظيم","aya_tafseer":"[1] يا أيها الناس احذروا عقاب الله بامتثال أوامره واجتناب نواهيه، إن ما يحدث عند قيام الساعة من أهوال وحركة شديدة للأرض، تتصدع منها كل جوانبها، شيء عظيم، لا يُقْدر قدره ولا يُبْلغ كنهه، ولا يعلم كيفيَّته إلا رب العالمين."},{"id":"2597","jozz":"17","page":"332","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"4","line_end":"6","aya_no":"2","aya_text":"يَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَمَّآ أَرۡضَعَتۡ وَتَضَعُ كُلُّ ذَاتِ حَمۡلٍ حَمۡلَهَا وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٞ","aya_text_emlaey":"يوم ترونها تذهل كل مرضعة عما أرضعت وتضع كل ذات حمل حملها وترى الناس سكارى وما هم بسكارى ولكن عذاب الله شديد","aya_tafseer":"[2] يوم ترون قيام الساعة تنسى الوالدةُ رضيعَها الذي ألقمته ثديها؛ لِمَا نزل بها من الكرب، وتُسْقط الحامل حملها من الرعب، وتغيب عقول الناس، فهم كالسكارى من شدة الهول والفزع، وليسوا بسكارى من الخمر، ولكن شدة الْهَول أفقدتهم عقولهم وإدراكهم."},{"id":"2598","jozz":"17","page":"332","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"6","line_end":"7","aya_no":"3","aya_text":"وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّبِعُ كُلَّ شَيۡطَٰنٖ مَّرِيدٖ","aya_text_emlaey":"ومن الناس من يجادل في الله بغير علم ويتبع كل شيطان مريد","aya_tafseer":"[3] وبعض رؤوس الكفر من الناس يخاصمون ويشككون في قدرة الله على البعث؛ جهلاً منهم بحقيقة هذه القدرة، واتباعاً لأئمة الضلال من كل شيطان متمرد على الله ورسله."},{"id":"2599","jozz":"17","page":"332","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"7","line_end":"8","aya_no":"4","aya_text":"كُتِبَ عَلَيۡهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهۡدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ","aya_text_emlaey":"كتب عليه أنه من تولاه فأنه يضله ويهديه إلى عذاب السعير","aya_tafseer":"[4] قضى الله وقدَّر على هذا الشيطان أنه يُضِل كلَّ من اتبعه، ولا يهديه إلى الحق، بل يسوقه إلى عذاب جهنم الموقدة جزاء اتباعه إياه."},{"id":"2600","jozz":"17","page":"332","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"9","line_end":"15","aya_no":"5","aya_text":"يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي رَيۡبٖ مِّنَ ٱلۡبَعۡثِ فَإِنَّا خَلَقۡنَٰكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ مِنۡ عَلَقَةٖ ثُمَّ مِن مُّضۡغَةٖ مُّخَلَّقَةٖ وَغَيۡرِ مُخَلَّقَةٖ لِّنُبَيِّنَ لَكُمۡۚ وَنُقِرُّ فِي ٱلۡأَرۡحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ نُخۡرِجُكُمۡ طِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡۖ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡلَا يَعۡلَمَ مِنۢ بَعۡدِ عِلۡمٖ شَيۡـٔٗاۚ وَتَرَى ٱلۡأَرۡضَ هَامِدَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡ وَأَنۢبَتَتۡ مِن كُلِّ زَوۡجِۭ بَهِيجٖ","aya_text_emlaey":"ياأيها الناس إن كنتم في ريب من البعث فإنا خلقناكم من تراب ثم من نطفة ثم من علقة ثم من مضغة مخلقة وغير مخلقة لنبين لكم ونقر في الأرحام ما نشاء إلى أجل مسمى ثم نخرجكم طفلا ثم لتبلغوا أشدكم ومنكم من يتوفى ومنكم من يرد إلى أرذل العمر لكيلا يعلم من بعد علم شيئا وترى الأرض هامدة فإذا أنـزلنا عليها الماء اهتزت وربت وأنبتت من كل زوج بهيج","aya_tafseer":"[5] يا أيها الناس إن كنتم في شك من أن الله يُحيي الموتى فإنَّا خلقنا أباكم آدم من تراب، ثم تناسلت ذريته من نطفة، هي المنيُّ يقذفه الرجل في رحم المرأة، فيتحول بقدرة الله إلى علقة، وهي الدم الأحمر الغليظ، ثم إلى مضغة، وهي قطعة لحم صغيرة قَدْر ما يُمْضَغ، فتكون تارة مخلَّقة، أي تامة الخلق تنتهي إلى خروج الجنين حيّاً، وغير تامة الخلق تارة أخرى، فتسقط لغير تمام؛ لنبيِّن لكم تمام قدرتنا بتصريف أطوار الخلق، ونبقي في الأرحام ما نشاء، وهو المخلَّق إلى وقت ولادته، وتكتمل الأطوار بولادة الأجنَّة أطفالاً صغاراً تكبَرُ حتى تبلغ الأشد، وهو وقت الشباب والقوة واكتمال العقل، وبعض الأطفال قد يموت قبل ذلك، وبعضهم يكبَرُ حتى يبلغ سن الهرم وضَعْف العقل؛ فلا يعلم هذا المعمَّر شيئاً مما كان يعلمه قبل ذلك. وترى الأرض يابسةً ميتة لا نبات فيها، فإذا أنزلنا عليها الماء تحركت بالنبات تتفتح عنه، وارتفعت وزادت لارتوائها، وأنبتت من كل نوع من أنواع النبات الحسن الذي يَسُرُّ الناظرين."},{"id":"2601","jozz":"17","page":"333","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"1","line_end":"2","aya_no":"6","aya_text":"ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّهُۥ يُحۡيِ ٱلۡمَوۡتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","aya_text_emlaey":"ذلك بأن الله هو الحق وأنه يحى الموتى وأنه على كل شيء قدير","aya_tafseer":"[6] ذلك المذكور مما تقدَّم من آيات قدرة الله تعالى، فيه دلالة قاطعة على أن الله سبحانه وتعالى هو الرب المعبود بحق، الذي لا تنبغي العبادة إلا له، وهو يُحيي الموتى، وهو قادر على كل شيء."},{"id":"2602","jozz":"17","page":"333","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"2","line_end":"3","aya_no":"7","aya_text":"وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةٞ لَّا رَيۡبَ فِيهَا وَأَنَّ ٱللَّهَ يَبۡعَثُ مَن فِي ٱلۡقُبُورِ","aya_text_emlaey":"وأن الساعة آتية لا ريب فيها وأن الله يبعث من في القبور","aya_tafseer":"[7] وأن ساعة البعث آتية لا شك في ذلك، وأن الله يبعث الموتى مِن قبورهم لحسابهم وجزائهم."},{"id":"2603","jozz":"17","page":"333","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"3","line_end":"4","aya_no":"8","aya_text":"وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَلَا هُدٗى وَلَا كِتَٰبٖ مُّنِيرٖ","aya_text_emlaey":"ومن الناس من يجادل في الله بغير علم ولا هدى ولا كتاب منير","aya_tafseer":"[8] ومن الكفار مَن يجادل بالباطل في الله وتوحيده واختياره رسوله -صلى الله عليه وسلم- وإنزاله القرآن، وذلك الجدال بغير علم، ولا بيان، ولا كتاب من الله فيه برهان وحجة واضحة،"},{"id":"2604","jozz":"17","page":"333","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"4","line_end":"5","aya_no":"9","aya_text":"ثَانِيَ عِطۡفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِۖ لَهُۥ فِي ٱلدُّنۡيَا خِزۡيٞۖ وَنُذِيقُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ عَذَابَ ٱلۡحَرِيقِ","aya_text_emlaey":"ثاني عطفه ليضل عن سبيل الله له في الدنيا خزي ونذيقه يوم القيامة عذاب الحريق","aya_tafseer":"[9] لاوياً عنقه في تكبر، معرضاً عن الحق؛ ليصد غيره عن الدخول في دين الله، فسوف يلقى خزياً في الدنيا باندحاره وافتضاح أمره، ونحرقه يوم القيامة بالنار."},{"id":"2605","jozz":"17","page":"333","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"5","line_end":"6","aya_no":"10","aya_text":"ذَٰلِكَ بِمَا قَدَّمَتۡ يَدَاكَ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّٰمٖ لِّلۡعَبِيدِ","aya_text_emlaey":"ذلك بما قدمت يداك وأن الله ليس بظلام للعبيد","aya_tafseer":"[10] ويقال له: ذلك العذاب بسبب ما فَعَلْتَ من المعاصي واكتسبت من الآثام، والله لا يعذب أحداً بغير ذنب."},{"id":"2606","jozz":"17","page":"333","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"6","line_end":"9","aya_no":"11","aya_text":"وَمِنَ ٱلنَّاسِ مَن يَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفٖۖ فَإِنۡ أَصَابَهُۥ خَيۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ أَصَابَتۡهُ فِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ خَسِرَ ٱلدُّنۡيَا وَٱلۡأٓخِرَةَۚ ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ","aya_text_emlaey":"ومن الناس من يعبد الله على حرف فإن أصابه خير اطمأن به وإن أصابته فتنة انقلب على وجهه خسر الدنيا والآخرة ذلك هو الخسران المبين","aya_tafseer":"[11] ومن الناس مَن يدخل في الإسلام على ضعف وشك، فيعبد الله على تردد، كالذي يقف على طرف جبل أو حائط لا يتماسك في وقفته، ويربط إيمانه بدنياه، فإن عاش في صحة وسَعَة استمر على عبادته، وإن حصل له ابتلاء بمكروه وشدة عزا شؤم ذلك إلى دينه، فرجع عنه كمن ينقلب على وجهه بعد استقامة، فهو بذلك قد خسر الدنيا؛ إذ لا يغيِّر كفرُه ما قُدِّر له في دنياه، وخسر الآخرة بدخوله النار، وذلك خسران بيِّن واضح. ً."},{"id":"2607","jozz":"17","page":"333","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"9","line_end":"10","aya_no":"12","aya_text":"يَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ","aya_text_emlaey":"يدعو من دون الله ما لا يضره وما لا ينفعه ذلك هو الضلال البعيد","aya_tafseer":"[12] يعبد ذلك الخاسر من دون الله ما لا يضره إن تركه، ولا ينفعه إذا عبده، ذلك هو الضلال البعيد عن الحق.ً."},{"id":"2608","jozz":"17","page":"333","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"10","line_end":"11","aya_no":"13","aya_text":"يَدۡعُواْ لَمَن ضَرُّهُۥٓ أَقۡرَبُ مِن نَّفۡعِهِۦۚ لَبِئۡسَ ٱلۡمَوۡلَىٰ وَلَبِئۡسَ ٱلۡعَشِيرُ","aya_text_emlaey":"يدعو لمن ضره أقرب من نفعه لبئس المولى ولبئس العشير","aya_tafseer":"[13] يدعو مَن ضررُه المحقق أقرب من نفعه، قبح ذلك المعبود نصيراً، وقبح عشيراً."},{"id":"2609","jozz":"17","page":"333","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"12","line_end":"13","aya_no":"14","aya_text":"إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ","aya_text_emlaey":"إن الله يدخل الذين آمنوا وعملوا الصالحات جنات تجري من تحتها الأنهار إن الله يفعل ما يريد","aya_tafseer":"[14] إن الله يدخل الذين آمنوا بالله ورسوله، وثبتوا على ذلك، وعملوا الصالحات، جنات تجري من تحت قصورها وأشجارها الأنهار، إن الله يفعل ما يريد من ثواب أهل طاعته تفضلاً، وعقابِ أهل معصيته عدلاً."},{"id":"2610","jozz":"17","page":"333","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"13","line_end":"15","aya_no":"15","aya_text":"مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ فَلۡيَمۡدُدۡ بِسَبَبٍ إِلَى ٱلسَّمَآءِ ثُمَّ لۡيَقۡطَعۡ فَلۡيَنظُرۡ هَلۡ يُذۡهِبَنَّ كَيۡدُهُۥ مَا يَغِيظُ","aya_text_emlaey":"من كان يظن أن لن ينصره الله في الدنيا والآخرة فليمدد بسبب إلى السماء ثم ليقطع فلينظر هل يذهبن كيده ما يغيظ","aya_tafseer":"[15] من كان يعتقد أن الله تعالى لن يؤيد رسوله محمداً بالنصر في الدنيا بإظهار دينه، وفي الآخرة بإعلاء درجته، وعذابِ مَن كذَّبه، فلْيَمْدُدْ حبلاً إلى سقف بيته وليخنق به نفسه، ثم ليقطع ذلك الحبل، ثم لينظر: هل يُذْهِبنَّ ذلك ما يجد في نفسه من الغيظ؟ فإن الله تعالى ناصرٌ نبيه محمداً -صلى الله عليه وسلم- لا محالة."},{"id":"2611","jozz":"17","page":"334","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"1","line_end":"1","aya_no":"16","aya_text":"وَكَذَٰلِكَ أَنزَلۡنَٰهُ ءَايَٰتِۭ بَيِّنَٰتٖ وَأَنَّ ٱللَّهَ يَهۡدِي مَن يُرِيدُ","aya_text_emlaey":"وكذلك أنـزلناه آيات بينات وأن الله يهدي من يريد","aya_tafseer":"[16] وكما أقام الله الحجة من دلائل قدرته على الكافرين بالبعث أنزل القرآن، آياته واضحة في لفظها ومعناها، يهدي بها الله مَن أراد هدايته؛ لأنه لا هادي سواه."},{"id":"2612","jozz":"17","page":"334","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"2","line_end":"4","aya_no":"17","aya_text":"إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلۡمَجُوسَ وَٱلَّذِينَ أَشۡرَكُوٓاْ إِنَّ ٱللَّهَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ","aya_text_emlaey":"إن الذين آمنوا والذين هادوا والصابئين والنصارى والمجوس والذين أشركوا إن الله يفصل بينهم يوم القيامة إن الله على كل شيء شهيد","aya_tafseer":"[17] إن الذين آمنوا بالله ورسوله محمدٍ -صلى الله عليه وسلم-، واليهود، والصابئين (وهم قوم باقون على فطرتهم ولا دين مقرر لهم يتبعونه)، والنصارى، والمجوس (وهم عبدة النار)، والذين أشركوا (وهم عبدة الأوثان)، إن الله يفصل بينهم جميعاً يوم القيامة فيدخل المؤمنين الجنة، ويدخل الكافرين النار، إن الله على كل شيء شهيد، شهد أعمال العباد كلَّها، وأحصاها وحفظها، وسيجازي كُلّاً بما يستحق؛ جزاء وفاقاً للأعمال التي عملوها."},{"id":"2613","jozz":"17","page":"334","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"4","line_end":"8","aya_no":"18","aya_text":"أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَسۡجُدُۤ لَهُۥۤ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٞ مِّنَ ٱلنَّاسِۖ وَكَثِيرٌ حَقَّ عَلَيۡهِ ٱلۡعَذَابُۗ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكۡرِمٍۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يَشَآءُ۩","aya_text_emlaey":"ألم تر أن الله يسجد له من في السموات ومن في الأرض والشمس والقمر والنجوم والجبال والشجر والدواب وكثير من الناس وكثير حق عليه العذاب ومن يهن الله فما له من مكرم إن الله يفعل ما يشاء","aya_tafseer":"[18] ألم تعلم -أيها الرسول- أن الله سبحانه يسجد له خاضعاً منقاداً مَن في السموات من الملائكة، ومَن في الأرض من المخلوقات، والشَّمسُ والقمر والنجوم والجبال والشجر والدوابُّ؟ ولله يسجد طاعة واختياراً كثير من الناس، وهم المؤمنون، وكثير من الناس حق عليه العذاب فهو مهين، وأيُّ إنسان يهنه الله فليس له أحد يكرمه. إن الله يفعل في خلقه ما يشاء وَفْقَ حكمته."},{"id":"2614","jozz":"17","page":"334","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"8","line_end":"10","aya_no":"19","aya_text":"۞ هَٰذَانِ خَصۡمَانِ ٱخۡتَصَمُواْ فِي رَبِّهِمۡۖ فَٱلَّذِينَ كَفَرُواْ قُطِّعَتۡ لَهُمۡ ثِيَابٞ مِّن نَّارٖ يُصَبُّ مِن فَوۡقِ رُءُوسِهِمُ ٱلۡحَمِيمُ","aya_text_emlaey":"هذان خصمان اختصموا في ربهم فالذين كفروا قطعت لهم ثياب من نار يصب من فوق رءوسهم الحميم","aya_tafseer":"[19] هذان فريقان اختلفوا في ربهم: أهل الإيمان وأهل الكفر، كل يدَّعي أنه محقٌّ، فالذين كفروا يحيط بهم العذاب في هيئة ثياب جُعلت لهم من نار يَلْبَسونها، فتشوي أجسادهم، ويُصبُّ على رؤوسهم الماء المتناهي في حره،"},{"id":"2615","jozz":"17","page":"334","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"10","line_end":"11","aya_no":"20","aya_text":"يُصۡهَرُ بِهِۦ مَا فِي بُطُونِهِمۡ وَٱلۡجُلُودُ","aya_text_emlaey":"يصهر به ما في بطونهم والجلود","aya_tafseer":"[20] ويَنزِل إلى أجوافهم فيذيب ما فيها، حتى ينفُذ إلى جلودهم فيشويها فتسقط،"},{"id":"2616","jozz":"17","page":"334","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"11","line_end":"11","aya_no":"21","aya_text":"وَلَهُم مَّقَٰمِعُ مِنۡ حَدِيدٖ","aya_text_emlaey":"ولهم مقامع من حديد","aya_tafseer":"[21] وتضربهم الملائكة على رؤوسهم بمطارق من حديد."},{"id":"2617","jozz":"17","page":"334","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"11","line_end":"13","aya_no":"22","aya_text":"كُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَا مِنۡ غَمٍّ أُعِيدُواْ فِيهَا وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ","aya_text_emlaey":"كلما أرادوا أن يخرجوا منها من غم أعيدوا فيها وذوقوا عذاب الحريق","aya_tafseer":"[22] كلما حاولوا الخروج من النار -لشدة غمِّهم وكربهم- أعيدوا للعذاب فيها، وقيل لهم: ذوقوا عذاب النار المحرق."},{"id":"2618","jozz":"17","page":"334","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"13","line_end":"15","aya_no":"23","aya_text":"إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَلُؤۡلُؤٗاۖ وَلِبَاسُهُمۡ فِيهَا حَرِيرٞ","aya_text_emlaey":"إن الله يدخل الذين آمنوا وعملوا الصالحات جنات تجري من تحتها الأنهار يحلون فيها من أساور من ذهب ولؤلؤا ولباسهم فيها حرير","aya_tafseer":"[23] إن الله تعالى يدخل أهل الإيمان والعمل الصالح جنات نعيمها دائم، تجري مِن تحت قصورها وأشجارها الأنهار، يُزَيَّنون فيها بأساور الذهب وباللؤلؤ، ولباسهم المعتاد في الجنة الحرير رجالاً ونساءً."},{"id":"2619","jozz":"17","page":"335","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"1","line_end":"1","aya_no":"24","aya_text":"وَهُدُوٓاْ إِلَى ٱلطَّيِّبِ مِنَ ٱلۡقَوۡلِ وَهُدُوٓاْ إِلَىٰ صِرَٰطِ ٱلۡحَمِيدِ","aya_text_emlaey":"وهدوا إلى الطيب من القول وهدوا إلى صراط الحميد","aya_tafseer":"[24] لقد هداهم الله في الدنيا إلى طيب القول: من كلمة التوحيد وحَمْد الله والثناء عليه، وفي الآخرة إلى حمده على حسن العاقبة، كما هداهم من قبل إلى طريق الإسلام المحمود الموصل إلى الجنة."},{"id":"2620","jozz":"17","page":"335","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"2","line_end":"4","aya_no":"25","aya_text":"إِنَّ ٱلَّذِينَ كَفَرُواْ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ ٱلَّذِي جَعَلۡنَٰهُ لِلنَّاسِ سَوَآءً ٱلۡعَٰكِفُ فِيهِ وَٱلۡبَادِۚ وَمَن يُرِدۡ فِيهِ بِإِلۡحَادِۭ بِظُلۡمٖ نُّذِقۡهُ مِنۡ عَذَابٍ أَلِيمٖ","aya_text_emlaey":"إن الذين كفروا ويصدون عن سبيل الله والمسجد الحرام الذي جعلناه للناس سواء العاكف فيه والباد ومن يرد فيه بإلحاد بظلم نذقه من عذاب أليم","aya_tafseer":"[25] إن الذين كفروا بالله وكذبوا بما جاءهم به محمد -صلى الله عليه وسلم-، ويمنعون غيرهم من الدخول في دين الله، ويصدون رسول الله -صلى الله عليه وسلم- والمؤمنين في عام «الحديبية» عن المسجد الحرام، الذي جعلناه لجميع المؤمنين، سواءً المقيم فيه والقادم إليه، لهم عذاب أليم موجع، ومن يرد في المسجد الحرام الميْلَ عن الحق ظلماً فيَعْصِ الله فيه، نُذِقْه مِن عذاب أليم موجع."},{"id":"2621","jozz":"17","page":"335","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"5","line_end":"7","aya_no":"26","aya_text":"وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ أَن لَّا تُشۡرِكۡ بِي شَيۡـٔٗا وَطَهِّرۡ بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ","aya_text_emlaey":"وإذ بوأنا لإبراهيم مكان البيت أن لا تشرك بي شيئا وطهر بيتي للطائفين والقائمين والركع السجود","aya_tafseer":"[26] واذكر -أيها النبي- إذ بَيَّنا لإبراهيم -عليه السلام- مكان البيت، وهيَّأناه له وقد كان غير معروف، وأمرناه ببنائه على تقوى من الله وتوحيده، وتطهيره من الكفر والبدع والنجاسات؛ ليكون رحاباً للطائفين به، والقائمين المصلين عنده."},{"id":"2622","jozz":"17","page":"335","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"7","line_end":"8","aya_no":"27","aya_text":"وَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ يَأۡتُوكَ رِجَالٗا وَعَلَىٰ كُلِّ ضَامِرٖ يَأۡتِينَ مِن كُلِّ فَجٍّ عَمِيقٖ","aya_text_emlaey":"وأذن في الناس بالحج يأتوك رجالا وعلى كل ضامر يأتين من كل فج عميق","aya_tafseer":"[27] وأعلِمْ -يا إبراهيم- الناس بوجوب الحج عليهم يأتوك على مختلف أحوالهم مشاةً وركباناً على كل ضامر من الإبل، وهو: (الخفيف اللحم من السَّيْر والأعمال لا من الهُزال)، يأتين من كل طريق بعيد؛"},{"id":"2623","jozz":"17","page":"335","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"8","line_end":"11","aya_no":"28","aya_text":"لِّيَشۡهَدُواْ مَنَٰفِعَ لَهُمۡ وَيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ فِيٓ أَيَّامٖ مَّعۡلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۖ فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡبَآئِسَ ٱلۡفَقِيرَ","aya_text_emlaey":"ليشهدوا منافع لهم ويذكروا اسم الله في أيام معلومات على ما رزقهم من بهيمة الأنعام فكلوا منها وأطعموا البائس الفقير","aya_tafseer":"[28] ليحضروا منافع لهم من: مغفرة ذنوبهم، وثواب أداء نسكهم وطاعتهم، وتكَسُّبِهم في تجاراتهم، وغير ذلك؛ وليذكروا اسم الله على ذَبْح ما يتقربون به من الإبل والبقر والغنم في أيام معيَّنة هي: عاشر ذي الحجة وثلاثة أيام بعده؛ شكراً لله على نعمه، وهم مأمورون أن يأكلوا مِن هذه الذبائح استحباباً، ويُطعموا منها الفقير الذي اشتد فقره."},{"id":"2624","jozz":"17","page":"335","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"11","line_end":"12","aya_no":"29","aya_text":"ثُمَّ لۡيَقۡضُواْ تَفَثَهُمۡ وَلۡيُوفُواْ نُذُورَهُمۡ وَلۡيَطَّوَّفُواْ بِٱلۡبَيۡتِ ٱلۡعَتِيقِ","aya_text_emlaey":"ثم ليقضوا تفثهم وليوفوا نذورهم وليطوفوا بالبيت العتيق","aya_tafseer":"[29] ثم ليكمل الحجاج ما بقي عليهم من النُّسُك، بإحلالهم وخروجهم من إحرامهم، وذلك بإزالة ما تراكم مِن وسخ في أبدانهم، وقص أظفارهم، وحلق شعرهم، وليوفوا بما أوجبوه على أنفسهم من الحج والعمرة والهدايا، وليطوفوا بالبيت العتيق القديم، الذي أعتقه الله مِن تسلُّط الجبارين عليه، وهو الكعبة."},{"id":"2625","jozz":"17","page":"335","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"13","line_end":"15","aya_no":"30","aya_text":"ذَٰلِكَۖ وَمَن يُعَظِّمۡ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيۡرٞ لَّهُۥ عِندَ رَبِّهِۦۗ وَأُحِلَّتۡ لَكُمُ ٱلۡأَنۡعَٰمُ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡۖ فَٱجۡتَنِبُواْ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَٰنِ وَٱجۡتَنِبُواْ قَوۡلَ ٱلزُّورِ","aya_text_emlaey":"ذلك ومن يعظم حرمات الله فهو خير له عند ربه وأحلت لكم الأنعام إلا ما يتلى عليكم فاجتنبوا الرجس من الأوثان واجتنبوا قول الزور","aya_tafseer":"[30] ذلك الذي أمر الله به مِن قضاء التفث والوفاء بالنذور والطواف بالبيت، هو ما أوجبه الله عليكم فعظِّموه، ومن يعظم حرمات الله، ومنها مناسكه بأدائها كاملة خالصة لله، فهو خير له في الدنيا والآخرة. وأحلَّ الله لكم أَكْلَ الأنعام إلا ما حرَّمه فيما يتلى عليكم في القرآن من الميتة وغيرها فاجتنبوه. وفي هذا إبطال ما كانت العرب تحرِّمه من بعض الأنعام. وابتعِدوا عن القذارة التي هي الأوثان، وعن الكذب الذي هو الافتراء على الله."},{"id":"2626","jozz":"17","page":"336","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"1","line_end":"2","aya_no":"31","aya_text":"حُنَفَآءَ لِلَّهِ غَيۡرَ مُشۡرِكِينَ بِهِۦۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخۡطَفُهُ ٱلطَّيۡرُ أَوۡ تَهۡوِي بِهِ ٱلرِّيحُ فِي مَكَانٖ سَحِيقٖ","aya_text_emlaey":"حنفاء لله غير مشركين به ومن يشرك بالله فكأنما خر من السماء فتخطفه الطير أو تهوي به الريح في مكان سحيق","aya_tafseer":"[31] مستقيمين لله على إخلاص العمل له، مقبلين عليه بعبادته وحده وإفراده بالطاعة، معرضين عما سواه بنبذ الشرك، فإنَّه مَن يشرك بالله شيئاً، فمثله -في بُعْده عن الهدى، وفي هلاكه وسقوطه من رفيع الإيمان إلى حضيض الكفر، وتخطُّف الشياطين له من كل جانب- كمثل مَن سقط من السماء: فإما أن تخطفه الطير فتقطع أعضاءه، وإما أن تأخذه عاصفة شديدة من الريح، فتقذفه في مكان بعيد أشدَّ البعد."},{"id":"2627","jozz":"17","page":"336","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"3","line_end":"3","aya_no":"32","aya_text":"ذَٰلِكَۖ وَمَن يُعَظِّمۡ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ","aya_text_emlaey":"ذلك ومن يعظم شعائر الله فإنها من تقوى القلوب","aya_tafseer":"[32] ذلك ما أمر الله به مِن توحيده وإخلاص العبادة له. ومن يمتثل أمر الله ويُعَظِّم معالم الدين، ومنها أعمال الحج وأماكنه، والذبائح التي تُذْبح فيه، وذلك باستحسانها واستسمانها، فهذا التعظيم مِن أفعال أصحاب القلوب المتصفة بتقوى الله وخشيته."},{"id":"2628","jozz":"17","page":"336","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"4","line_end":"5","aya_no":"33","aya_text":"لَكُمۡ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ مَحِلُّهَآ إِلَى ٱلۡبَيۡتِ ٱلۡعَتِيقِ","aya_text_emlaey":"لكم فيها منافع إلى أجل مسمى ثم محلها إلى البيت العتيق","aya_tafseer":"[33] لكم في هذه الهدايا منافع تنتفعون بها من الصوف واللبن والركوب، وغير ذلك مما لا يضرها إلى وقت ذبحها عند البيت العتيق، وهو الحرم كله."},{"id":"2629","jozz":"17","page":"336","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"5","line_end":"7","aya_no":"34","aya_text":"وَلِكُلِّ أُمَّةٖ جَعَلۡنَا مَنسَكٗا لِّيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۗ فَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞ فَلَهُۥٓ أَسۡلِمُواْۗ وَبَشِّرِ ٱلۡمُخۡبِتِينَ","aya_text_emlaey":"ولكل أمة جعلنا منسكا ليذكروا اسم الله على ما رزقهم من بهيمة الأنعام فإلهكم إله واحد فله أسلموا وبشر المخبتين","aya_tafseer":"[34] ولكل جماعة مؤمنة سلفت، جعلنا لها مناسك مِنَ الذبح وإراقة الدماء؛ وذلك ليذكروا اسم الله تعالى عند ذبح ما رزقهم مِن هذه الأنعام ويشكروا له. فإلهكم -أيها الناس- إله واحد هو الله فانقادوا لأمره وأمر رسوله. وبشِّر –أيها النبي- المتواضعين الخاضعين لربهم بخيرَي الدنيا والآخرة."},{"id":"2630","jozz":"17","page":"336","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"7","line_end":"9","aya_no":"35","aya_text":"ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَٱلصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمۡ وَٱلۡمُقِيمِي ٱلصَّلَوٰةِ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","aya_text_emlaey":"الذين إذا ذكر الله وجلت قلوبهم والصابرين على ما أصابهم والمقيمي الصلاة ومما رزقناهم ينفقون","aya_tafseer":"[35] هؤلاء المتواضعون الخاشعون مِن صفاتهم أنهم إذا ذُكِر الله وحده خافوا عقابه، وحَذِروا مخالفته، وإذا أصابهم بأس وشدة صبروا على ذلك مؤملين الثواب من الله عز وجل، وأدَّوا الصلاة تامة، وهم مع ذلك ينفقون مما رزقهم الله في الواجب عليهم مِن زكاة ونفقة عيال، وعلى مَن وَجَبَتْ عليهم نفقته، وفي سبيل الله، والنفقات المستحبة."},{"id":"2631","jozz":"17","page":"336","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"9","line_end":"12","aya_no":"36","aya_text":"وَٱلۡبُدۡنَ جَعَلۡنَٰهَا لَكُم مِّن شَعَٰٓئِرِ ٱللَّهِ لَكُمۡ فِيهَا خَيۡرٞۖ فَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهَا صَوَآفَّۖ فَإِذَا وَجَبَتۡ جُنُوبُهَا فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡقَانِعَ وَٱلۡمُعۡتَرَّۚ كَذَٰلِكَ سَخَّرۡنَٰهَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ","aya_text_emlaey":"والبدن جعلناها لكم من شعائر الله لكم فيها خير فاذكروا اسم الله عليها صواف فإذا وجبت جنوبها فكلوا منها وأطعموا القانع والمعتر كذلك سخرناها لكم لعلكم تشكرون","aya_tafseer":"[36] وجعلنا لكم نَحْرَ ما سَمُن من الإبل والبقر من شعائر الدين وأعلامه؛ لتتقربوا بها إلى الله، لكم فيها -أيها المتقربون- خير في منافعها من الأكل والصدقة والثواب والأجر، فقولوا عند ذبحها: بسم الله. وتُنْحَر الإبل واقفة قد صُفَّتْ ثلاث من قوائمها وقُيِّدت الرابعة، فإذا سقطت على الأرض جنوبها فقد حلَّ أكلها، فليأكل منها مقرِّبوها تعبداً ويُطْعِمُوا منها القانع -وهو الفقير الذي لم يسأل تعففاً- والمعترَّ الذي يسأل لحاجته، هكذا سخَّر الله البُدْن لكم، لعلكم تشكرون الله على تسخيرها لكم."},{"id":"2632","jozz":"17","page":"336","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"12","line_end":"14","aya_no":"37","aya_text":"لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقۡوَىٰ مِنكُمۡۚ كَذَٰلِكَ سَخَّرَهَا لَكُمۡ لِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡۗ وَبَشِّرِ ٱلۡمُحۡسِنِينَ","aya_text_emlaey":"لن ينال الله لحومها ولا دماؤها ولكن يناله التقوى منكم كذلك سخرها لكم لتكبروا الله على ما هداكم وبشر المحسنين","aya_tafseer":"[37] لن ينال اللهَ مِن لحوم هذه الذبائح ولا من دمائها شيء، ولكن يناله الإخلاص فيها، وأن يكون القصد بها وجه الله وحده، كذلك ذللها لكم -أيها المتقربون-؛ لتعظموا الله، وتشكروا له على ما هداكم من الحق، فإنه أهلٌ لذلك. وبشِّر -أيها النبي- المحسنين بعبادة الله وحده، والمحسنين إلى خلقه بكل خير وفلاح."},{"id":"2633","jozz":"17","page":"336","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"14","line_end":"15","aya_no":"38","aya_text":"۞ إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓاْۗ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٖ كَفُورٍ","aya_text_emlaey":"إن الله يدافع عن الذين آمنوا إن الله لا يحب كل خوان كفور","aya_tafseer":"[38] إن الله تعالى يدفع عن المؤمنين عدوان الكفار، وكيد الأشرار؛ لأنه عز وجل لا يحب كل خوَّان لأمانة ربه، جحود لنعمته."},{"id":"2634","jozz":"17","page":"337","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"1","line_end":"2","aya_no":"39","aya_text":"أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمۡ ظُلِمُواْۚ وَإِنَّ ٱللَّهَ عَلَىٰ نَصۡرِهِمۡ لَقَدِيرٌ","aya_text_emlaey":"أذن للذين يقاتلون بأنهم ظلموا وإن الله على نصرهم لقدير","aya_tafseer":"[39] كان المسلمون في أول أمرهم ممنوعين من قتال الكفار، مأمورين بالصبر على أذاهم، فلما بلغ أذى المشركين مداه، وخرج النبي -صلى الله عليه وسلم- من «مكة» مهاجراً إلى «المدينة»، وأصبح للإسلام قوة أَذِنَ الله للمسلمين في القتال؛ بسبب ما وقع عليهم من الظلم والعدوان، وإن الله تعالى قادر على نصرهم وإذلال عدوِّهم."},{"id":"2635","jozz":"17","page":"337","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"2","line_end":"6","aya_no":"40","aya_text":"ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِم بِغَيۡرِ حَقٍّ إِلَّآ أَن يَقُولُواْ رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعٞ وَصَلَوَٰتٞ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ كَثِيرٗاۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ","aya_text_emlaey":"الذين أخرجوا من ديارهم بغير حق إلا أن يقولوا ربنا الله ولولا دفع الله الناس بعضهم ببعض لهدمت صوامع وبيع وصلوات ومساجد يذكر فيها اسم الله كثيرا ولينصرن الله من ينصره إن الله لقوي عزيز","aya_tafseer":"[40] الذين أُلجئوا إلى الخروج من ديارهم، لا لشيء فعلوه إلا لأنهم أسلموا وقالوا: ربنا الله وحده. ولولا ما شرعه الله مِن دَفْع الظلم الذي ينتفع به جميع أهل الأديان المنزَّلة، وردِّ الباطل بالقتال المأذون فيه لهُزِم الحقُّ في كل أمة ولخربت الأرض، وهُدِّمت فيها أماكن العبادة من صوامع الرهبان، وكنائس النصارى، ومعابد اليهود، ومساجد المسلمين التي يصلُّون فيها، ويذكرون اسم الله فيها كثيراً. ومن اجتهد في نصرة دين الله، فإن الله ناصره على عدوه. إن الله لَقوي لا يغالَب، عزيز لا يرام، قد قهر الخلائق وأخذ بنواصيهم."},{"id":"2636","jozz":"17","page":"337","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"6","line_end":"8","aya_no":"41","aya_text":"ٱلَّذِينَ إِن مَّكَّنَّٰهُمۡ فِي ٱلۡأَرۡضِ أَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ وَأَمَرُواْ بِٱلۡمَعۡرُوفِ وَنَهَوۡاْ عَنِ ٱلۡمُنكَرِۗ وَلِلَّهِ عَٰقِبَةُ ٱلۡأُمُورِ","aya_text_emlaey":"الذين إن مكناهم في الأرض أقاموا الصلاة وآتوا الزكاة وأمروا بالمعروف ونهوا عن المنكر ولله عاقبة الأمور","aya_tafseer":"[41] الذين وعدناهم بنصرنا هم الذين إنْ مكَّنَّاهم في الأرض، واستخلفناهم فيها بإظهارهم على عدوهم، أقاموا الصلاة بأدائها في أوقاتها بحدودها، وأخرجوا زكاة أموالهم إلى أهلها، وأمروا بكل ما أمر الله به مِن حقوقه وحقوق عباده، ونَهَوْا عن كل ما نهى الله عنه ورسوله. ولله وحده مصير الأمور كلها، والعاقبة للتقوى."},{"id":"2637","jozz":"17","page":"337","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"8","line_end":"9","aya_no":"42","aya_text":"وَإِن يُكَذِّبُوكَ فَقَدۡ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَعَادٞ وَثَمُودُ","aya_text_emlaey":"وإن يكذبوك فقد كذبت قبلهم قوم نوح وعاد وثمود","aya_tafseer":"[42] وإن يكذبك قومك -أيها الرسول- فقد سبقهم في تكذيب رسلهم قوم نوح، وعاد، وثمود،"},{"id":"2638","jozz":"17","page":"337","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"9","line_end":"10","aya_no":"43","aya_text":"وَقَوۡمُ إِبۡرَٰهِيمَ وَقَوۡمُ لُوطٖ","aya_text_emlaey":"وقوم إبراهيم وقوم لوط","aya_tafseer":"[43] وقوم إبراهيم، وقوم لوط،"},{"id":"2639","jozz":"17","page":"337","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"10","line_end":"11","aya_no":"44","aya_text":"وَأَصۡحَٰبُ مَدۡيَنَۖ وَكُذِّبَ مُوسَىٰۖ فَأَمۡلَيۡتُ لِلۡكَٰفِرِينَ ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ نَكِيرِ","aya_text_emlaey":"وأصحاب مدين وكذب موسى فأمليت للكافرين ثم أخذتهم فكيف كان نكير","aya_tafseer":"[44] وأصحاب «مدين» الذين كذبوا شعيباً، وكذَّب فرعونُ وقومُه موسى، فلم أعاجل هذه الأمم بالعقوبة، بل أمهلتها، ثم أخذتُ كُلّاً منهم بالعذاب، فكيف كان إنكاري عليهم كفرهم وتكذيبهم، وكيف كان تبديلُ ما كان بهم مِن نعمة بالعذاب والهلاك؟"},{"id":"2640","jozz":"17","page":"337","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"11","line_end":"13","aya_no":"45","aya_text":"فَكَأَيِّن مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا وَهِيَ ظَالِمَةٞ فَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئۡرٖ مُّعَطَّلَةٖ وَقَصۡرٖ مَّشِيدٍ","aya_text_emlaey":"فكأين من قرية أهلكناها وهي ظالمة فهي خاوية على عروشها وبئر معطلة وقصر مشيد","aya_tafseer":"[45] فكثيراً من القرى الظالمة بكفرها أهلكنا أهلها، فديارهم مهدَّمة خَلَتْ مِن سكانها، وآبارها لا يُستقى منها، وقصورها العالية المزخرفة لم تدفع عن أهلها سوء العذاب."},{"id":"2641","jozz":"17","page":"337","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"13","line_end":"15","aya_no":"46","aya_text":"أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَتَكُونَ لَهُمۡ قُلُوبٞ يَعۡقِلُونَ بِهَآ أَوۡ ءَاذَانٞ يَسۡمَعُونَ بِهَاۖ فَإِنَّهَا لَا تَعۡمَى ٱلۡأَبۡصَٰرُ وَلَٰكِن تَعۡمَى ٱلۡقُلُوبُ ٱلَّتِي فِي ٱلصُّدُورِ","aya_text_emlaey":"أفلم يسيروا في الأرض فتكون لهم قلوب يعقلون بها أو آذان يسمعون بها فإنها لا تعمى الأبصار ولكن تعمى القلوب التي في الصدور","aya_tafseer":"[46] أفلم يَسِر المكذبون من قريش في الأرض ليشاهدوا آثار المهلَكين، فيتفكروا بعقولهم، فيعتبروا، ويسمعوا أخبارهم سماع تدبُّر فيتعظوا؟ فإن العمى ليس عمى البصر، وإنما العمى المُهْلِك هو عمى البصيرة عن إدراك الحق والاعتبار."},{"id":"2642","jozz":"17","page":"338","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"1","line_end":"2","aya_no":"47","aya_text":"وَيَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَن يُخۡلِفَ ٱللَّهُ وَعۡدَهُۥۚ وَإِنَّ يَوۡمًا عِندَ رَبِّكَ كَأَلۡفِ سَنَةٖ مِّمَّا تَعُدُّونَ","aya_text_emlaey":"ويستعجلونك بالعذاب ولن يخلف الله وعده وإن يوما عند ربك كألف سنة مما تعدون","aya_tafseer":"[47] ويستعجلك -أيها الرسول- كفار قريش -لشدة جهلهم- بالعذاب الذي أنذرتهم به لمَّا أصروا على الكفر، ولن يخلف الله ما وعدهم به من العذاب فلا بدَّ من وقوعه، وقد عجَّل لهم في الدنيا ذلك في يوم «بدر». وإن يوماً من الأيام عند الله -وهو يوم القيامة- كألف سنة مما تَعُدُّون من سني الدنيا."},{"id":"2643","jozz":"17","page":"338","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"2","line_end":"3","aya_no":"48","aya_text":"وَكَأَيِّن مِّن قَرۡيَةٍ أَمۡلَيۡتُ لَهَا وَهِيَ ظَالِمَةٞ ثُمَّ أَخَذۡتُهَا وَإِلَيَّ ٱلۡمَصِيرُ","aya_text_emlaey":"وكأين من قرية أمليت لها وهي ظالمة ثم أخذتها وإلي المصير","aya_tafseer":"[48] وكثير من القرى كانت ظالمة بإصرار أهلها على الكفر، فأمهلْتُهم ولم أعاجلهم بالعقوبة فاغتروا، ثم أخَذْتُهم بعذابي في الدنيا، وإليَّ مرجعهم بعد هلاكهم، فأعذبهم بما يستحقون."},{"id":"2644","jozz":"17","page":"338","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"4","line_end":"4","aya_no":"49","aya_text":"قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمۡ نَذِيرٞ مُّبِينٞ","aya_text_emlaey":"قل ياأيها الناس إنما أنا لكم نذير مبين","aya_tafseer":"[49] قل -أيها الرسول-: يا أيها الناس ما أنا إلا منذر لكم مبلِّغ عن الله رسالته.ً."},{"id":"2645","jozz":"17","page":"338","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"4","line_end":"5","aya_no":"50","aya_text":"فَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ","aya_text_emlaey":"فالذين آمنوا وعملوا الصالحات لهم مغفرة ورزق كريم","aya_tafseer":"[50] فالذين آمنوا بالله ورسوله، واستقر ذلك في قلوبهم، وعملوا الأعمال الصالحة، لهم عند الله عفو عن ذنوبهم ومغفرة يستر بها ما صدر عنهم من معصية، ورزق حسن لا ينقطع وهو الجنة."},{"id":"2646","jozz":"17","page":"338","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"6","line_end":"7","aya_no":"51","aya_text":"وَٱلَّذِينَ سَعَوۡاْ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ","aya_text_emlaey":"والذين سعوا في آياتنا معاجزين أولئك أصحاب الجحيم","aya_tafseer":"[51] والذين اجتهدوا في الكيد لإبطال آيات القرآن بالتكذيب مُشاقين مغالبين، أولئك هم أهل النار الموقدة، يدخلونها ويبقون فيها أبداً."},{"id":"2647","jozz":"17","page":"338","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"7","line_end":"9","aya_no":"52","aya_text":"وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٖ وَلَا نَبِيٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلۡقَى ٱلشَّيۡطَٰنُ فِيٓ أُمۡنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلۡقِي ٱلشَّيۡطَٰنُ ثُمَّ يُحۡكِمُ ٱللَّهُ ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ","aya_text_emlaey":"وما أرسلنا من قبلك من رسول ولا نبي إلا إذا تمنى ألقى الشيطان في أمنيته فينسخ الله ما يلقي الشيطان ثم يحكم الله آياته والله عليم حكيم","aya_tafseer":"[52] وما أرسلنا مِن قبلك -أيها الرسول- من رسول ولا نبي إلا إذا قرأ ما أُرسِل به من الآيات ألقى الشيطان في قراءته الوساوس والشبهات؛ ليصدَّ الناس عن اتباع ما يقرؤه ويتلوه، لكن الله يبطل كيد الشيطان، فيزيل وساوسه، ويثبت آياته الواضحات. والله عليم بما كان ويكون، لا تخفى عليه خافية، حكيم في تقديره وأمره."},{"id":"2648","jozz":"17","page":"338","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"9","line_end":"11","aya_no":"53","aya_text":"لِّيَجۡعَلَ مَا يُلۡقِي ٱلشَّيۡطَٰنُ فِتۡنَةٗ لِّلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡقَاسِيَةِ قُلُوبُهُمۡۗ وَإِنَّ ٱلظَّٰلِمِينَ لَفِي شِقَاقِۭ بَعِيدٖ","aya_text_emlaey":"ليجعل ما يلقي الشيطان فتنة للذين في قلوبهم مرض والقاسية قلوبهم وإن الظالمين لفي شقاق بعيد","aya_tafseer":"[53] وما كان هذا الفعل مِنَ الشيطان إلا ليجعله الله اختباراً للذين في قلوبهم شك ونفاق، ولقساة القلوب من المشركين الذين لا يؤثِّر فيهم زجر. وإن الظالمين مِن هؤلاء وأولئك في عداوة شديدة لله ورسوله وخلافٍ للحق بعيد عن الصواب."},{"id":"2649","jozz":"17","page":"338","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"11","line_end":"14","aya_no":"54","aya_text":"وَلِيَعۡلَمَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَيُؤۡمِنُواْ بِهِۦ فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓاْ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","aya_text_emlaey":"وليعلم الذين أوتوا العلم أنه الحق من ربك فيؤمنوا به فتخبت له قلوبهم وإن الله لهاد الذين آمنوا إلى صراط مستقيم","aya_tafseer":"[54] وليعلم أهل العلم الذين يفرقون بعلمهم بين الحق والباطل أن القرآن الكريم هو الحق النازل من عند الله عليك أيها الرسول، لا شبهة فيه، ولا سبيل للشيطان إليه، فيزداد به إيمانهم، وتخضع له قلوبهم. وإن الله لهادي الذين آمنوا به وبرسوله إلى طريق الحق الواضح، وهو الإسلام ينقذهم به من الضلال."},{"id":"2650","jozz":"17","page":"338","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"14","line_end":"15","aya_no":"55","aya_text":"وَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ فِي مِرۡيَةٖ مِّنۡهُ حَتَّىٰ تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةً أَوۡ يَأۡتِيَهُمۡ عَذَابُ يَوۡمٍ عَقِيمٍ","aya_text_emlaey":"ولا يزال الذين كفروا في مرية منه حتى تأتيهم الساعة بغتة أو يأتيهم عذاب يوم عقيم","aya_tafseer":"[55] ولا يزال الكافرون المكذبون في شك مما جئتَهم به من القرآن إلى أن تأتيهم الساعة فجأة، وهم على تكذيبهم، أو يأتيهم عذاب يوم لا خير فيه لهم، وهو يوم القيامة."},{"id":"2651","jozz":"17","page":"339","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"1","line_end":"2","aya_no":"56","aya_text":"ٱلۡمُلۡكُ يَوۡمَئِذٖ لِّلَّهِ يَحۡكُمُ بَيۡنَهُمۡۚ فَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فِي جَنَّٰتِ ٱلنَّعِيمِ","aya_text_emlaey":"الملك يومئذ لله يحكم بينهم فالذين آمنوا وعملوا الصالحات في جنات النعيم","aya_tafseer":"[56] المُلْك والسلطان في هذا اليوم لله وحده، وهو سبحانه يقضي بين المؤمنين والكافرين. فالذين آمنوا بالله ورسوله وعملوا الأعمال الصالحة، لهم النعيم الدائم في الجنات."},{"id":"2652","jozz":"17","page":"339","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"2","line_end":"4","aya_no":"57","aya_text":"وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا فَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ","aya_text_emlaey":"والذين كفروا وكذبوا بآياتنا فأولئك لهم عذاب مهين","aya_tafseer":"[57] .والذين جحدوا وحدانية الله وكذبوا رسوله وأنكروا آيات القرآن، فأولئك لهم عذاب يخزيهم ويهينهم في جهنم."},{"id":"2653","jozz":"17","page":"339","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"4","line_end":"6","aya_no":"58","aya_text":"وَٱلَّذِينَ هَاجَرُواْ فِي سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓاْ أَوۡ مَاتُواْ لَيَرۡزُقَنَّهُمُ ٱللَّهُ رِزۡقًا حَسَنٗاۚ وَإِنَّ ٱللَّهَ لَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ","aya_text_emlaey":"والذين هاجروا في سبيل الله ثم قتلوا أو ماتوا ليرزقنهم الله رزقا حسنا وإن الله لهو خير الرازقين","aya_tafseer":"[58] والذين خرجوا من ديارهم طلباً لرضا الله، ونصرة لدينه، مَن قُتل منهم وهو يجاهد الكفار، ومن مات منهم مِن غير قتال، لَيرزقَنَّهم الله الجنة ونعيمها الذي لا ينقطع ولا يزول، وإن الله سبحانه وتعالى لهو خير الرازقين."},{"id":"2654","jozz":"17","page":"339","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"6","line_end":"7","aya_no":"59","aya_text":"لَيُدۡخِلَنَّهُم مُّدۡخَلٗا يَرۡضَوۡنَهُۥۚ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمٞ","aya_text_emlaey":"ليدخلنهم مدخلا يرضونه وإن الله لعليم حليم","aya_tafseer":"[59] ليُدخلنَّهم الله المُدْخل الذي يحبونه وهو الجنة. وإن الله لَعليم بمن يخرج في سبيله، ومن يخرج طلباً للدنيا، حليم عمن عصاه، فلا يعاجلهم بالعقوبة."},{"id":"2655","jozz":"17","page":"339","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"7","line_end":"9","aya_no":"60","aya_text":"۞ ذَٰلِكَۖ وَمَنۡ عَاقَبَ بِمِثۡلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِيَ عَلَيۡهِ لَيَنصُرَنَّهُ ٱللَّهُۚ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ","aya_text_emlaey":"ذلك ومن عاقب بمثل ما عوقب به ثم بغي عليه لينصرنه الله إن الله لعفو غفور","aya_tafseer":"[60] ذلك الأمرُ الذي قصصنا عليك من إدخال المهاجرين الجنة، ومن اعتُدِي عليه وظُلم فقد أُذِن له أن يقابل الجاني بمثل فعلته، ولا حرج عليه، فإذا عاد الجاني إلى إيذائه وبغى، فإن الله ينصر المظلوم المعتدى عليه؛ إذ لا يجوز أن يُعْتَدى عليه بسبب انتصافه لنفسه. إن الله لعفوٌّ غفور، يعفو عن المذنبين فلا يعاجلهم بالعقوبة، ويغفر ذنوبهم."},{"id":"2656","jozz":"17","page":"339","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"9","line_end":"11","aya_no":"61","aya_text":"ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَأَنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٞ","aya_text_emlaey":"ذلك بأن الله يولج الليل في النهار ويولج النهار في الليل وأن الله سميع بصير","aya_tafseer":"[61] ذلك الذي شرع لكم تلك الأحكام العادلة هو الحق، وهو القادر على ما يشاء، ومِن قدرته أنه يدخل ما ينقص من ساعات الليل في ساعات النهار، ويدخل ما انتقص من ساعات النهار في ساعات الليل، وأن الله سميع لكل صوت، بصير بكل فعل، لا يخفى عليه شيء."},{"id":"2657","jozz":"17","page":"339","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"11","line_end":"12","aya_no":"62","aya_text":"ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ مِن دُونِهِۦ هُوَ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ","aya_text_emlaey":"ذلك بأن الله هو الحق وأن ما يدعون من دونه هو الباطل وأن الله هو العلي الكبير","aya_tafseer":"[62] ذلك بأن الله هو الإله الحق الذي لا تنبغي العبادة إلَّا له، وأن ما يعبده المشركون من دونه من الأصنام والأنداد هو الباطل الذي لا ينفع ولا يضرُّ، وأن الله هو العليُّ على خلقه ذاتاً وقَدْراً وقهراً، المتعالي عن الأشباه والأنداد، الكبير في ذاته، وأسمائه، وصفاته، فهو أكبر من كل شيء."},{"id":"2658","jozz":"17","page":"339","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"13","line_end":"14","aya_no":"63","aya_text":"أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَتُصۡبِحُ ٱلۡأَرۡضُ مُخۡضَرَّةًۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٞ","aya_text_emlaey":"ألم تر أن الله أنـزل من السماء ماء فتصبح الأرض مخضرة إن الله لطيف خبير","aya_tafseer":"[63] ألم ترَ -أيها الرسول- أن الله أنزل من السماء مطراً، فتصبح الأرض مخضرة بما ينبت فيها من النبات؟ إن الله لطيف بعباده باستخراج النبات من الأرض بذلك الماء، خبير بمصالحهم."},{"id":"2659","jozz":"17","page":"339","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"14","line_end":"15","aya_no":"64","aya_text":"لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ","aya_text_emlaey":"له ما في السموات وما في الأرض وإن الله لهو الغني الحميد","aya_tafseer":"[64] لله سبحانه وتعالى ما في السموات والأرض خلقاً وملكاً وعبودية، كلٌّ محتاج إلى تدبيره وإفضاله. وإن الله لهو الغني الذي لا يحتاج إلى شيء، المحمود في كل حال."},{"id":"2660","jozz":"17","page":"340","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"1","line_end":"3","aya_no":"65","aya_text":"أَلَمۡ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلۡأَرۡضِ وَٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِأَمۡرِهِۦ وَيُمۡسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلۡأَرۡضِ إِلَّا بِإِذۡنِهِۦٓۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ","aya_text_emlaey":"ألم تر أن الله سخر لكم ما في الأرض والفلك تجري في البحر بأمره ويمسك السماء أن تقع على الأرض إلا بإذنه إن الله بالناس لرءوف رحيم","aya_tafseer":"[65] ألم تر أن الله تعالى ذلَّل لكم ما في الأرض من الدواب والبهائم والزروع والثمار والجماد لركوبكم وطعامكم وكل منافعكم، كما ذلَّل لكم السفن تجري في البحر بقدرته وأمره، فتحملكم مع أمتعتكم إلى حيث تشاؤون من البلاد والأماكن، وهو الذي يمسك السماء فيحفظها؛ حتى لا تقع على الأرض فيهلك مَن عليها إلا بإذنه سبحانه بذلك؟ إن الله ليرحم الناس رحمة واسعة في عاجلهم وآجلهم، ومن رحمته بهم ما سخَّره لهم من هذه الأشياء وغيرها؛ تفضلاً منه عليهم."},{"id":"2661","jozz":"17","page":"340","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"3","line_end":"4","aya_no":"66","aya_text":"وَهُوَ ٱلَّذِيٓ أَحۡيَاكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡۗ إِنَّ ٱلۡإِنسَٰنَ لَكَفُورٞ","aya_text_emlaey":"وهو الذي أحياكم ثم يميتكم ثم يحييكم إن الإنسان لكفور","aya_tafseer":"[66] وهو الله تعالى الذي أحياكم بأن أوجدكم من العدم، ثم يميتكم عند انقضاء أعماركم، ثم يحييكم بالبعث لمحاسبتكم على أعمالكم. إن الإنسان لَجحود لما ظهر من الآيات الدالة على قدرة الله ووحدانيته."},{"id":"2662","jozz":"17","page":"340","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"5","line_end":"6","aya_no":"67","aya_text":"لِّكُلِّ أُمَّةٖ جَعَلۡنَا مَنسَكًا هُمۡ نَاسِكُوهُۖ فَلَا يُنَٰزِعُنَّكَ فِي ٱلۡأَمۡرِۚ وَٱدۡعُ إِلَىٰ رَبِّكَۖ إِنَّكَ لَعَلَىٰ هُدٗى مُّسۡتَقِيمٖ","aya_text_emlaey":"لكل أمة جعلنا منسكا هم ناسكوه فلا ينازعنك في الأمر وادع إلى ربك إنك لعلى هدى مستقيم","aya_tafseer":"[67] لكل أمة من الأمم الماضية جعلنا شريعة وعبادة أمرناهم بها، فهم عاملون بها، فلا ينازعَنَّك -أيها الرسول- مشركو قريش في شريعتك، وما أمرك الله به في المناسك وأنواع العبادات كلها، وادع إلى توحيد ربك وإخلاص العبادة له واتباع أمره، إنك لعلى دين قويم، لا اعوجاج فيه."},{"id":"2663","jozz":"17","page":"340","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"7","line_end":"7","aya_no":"68","aya_text":"وَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعۡلَمُ بِمَا تَعۡمَلُونَ","aya_text_emlaey":"وإن جادلوك فقل الله أعلم بما تعملون","aya_tafseer":"[68] وإن أصرُّوا على مجادلتك بالباطل فيما تدعوهم إليه فلا تجادلهم، بل قل لهم: الله أعلم بما تعملونه من الكفر والتكذيب، فهم معاندون مكابرون."},{"id":"2664","jozz":"17","page":"340","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"7","line_end":"8","aya_no":"69","aya_text":"ٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ","aya_text_emlaey":"الله يحكم بينكم يوم القيامة فيما كنتم فيه تختلفون","aya_tafseer":"[69] الله تعالى يحكم بين المسلمين والكافرين يوم القيامة في أمر اختلافهم في الدين. وفي هذه الآية أدب حسن في الرد على مَن جادل تعنتاً واستكباراً."},{"id":"2665","jozz":"17","page":"340","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"9","line_end":"10","aya_no":"70","aya_text":"أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِنَّ ذَٰلِكَ فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ","aya_text_emlaey":"ألم تعلم أن الله يعلم ما في السماء والأرض إن ذلك في كتاب إن ذلك على الله يسير","aya_tafseer":"[70] ألم تعلم -أيها الرسول- أن الله يعلم ما في السماء والأرض علماً كاملاً قد أثبته في اللوح المحفوظ؟ إن ذلك العلم أمر سهل على الله الذي لا يعجزه شيء."},{"id":"2666","jozz":"17","page":"340","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"10","line_end":"12","aya_no":"71","aya_text":"وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا وَمَا لَيۡسَ لَهُم بِهِۦ عِلۡمٞۗ وَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٖ","aya_text_emlaey":"ويعبدون من دون الله ما لم ينـزل به سلطانا وما ليس لهم به علم وما للظالمين من نصير","aya_tafseer":"[71] ويصر كفار قريش على الشرك بالله مع ظهور بطلان ما هم عليه، فهم يعبدون آلهة، لم يَنْزِل في كتاب مِن كتب الله برهان بأنها تصلح للعبادة، ولا علم لهم فيما اختلقوه، وافتروه على الله، وإنما هو أمر اتبعوا فيه آباءَهم بلا دليل. فإذا جاء وقت الحساب في الآخرة فليس للمشركين ناصر ينصرهم، أو يدفع عنهم العذاب."},{"id":"2667","jozz":"17","page":"340","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"12","line_end":"15","aya_no":"72","aya_text":"وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ تَعۡرِفُ فِي وُجُوهِ ٱلَّذِينَ كَفَرُواْ ٱلۡمُنكَرَۖ يَكَادُونَ يَسۡطُونَ بِٱلَّذِينَ يَتۡلُونَ عَلَيۡهِمۡ ءَايَٰتِنَاۗ قُلۡ أَفَأُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكُمُۚ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُواْۖ وَبِئۡسَ ٱلۡمَصِيرُ","aya_text_emlaey":"وإذا تتلى عليهم آياتنا بينات تعرف في وجوه الذين كفروا المنكر يكادون يسطون بالذين يتلون عليهم آياتنا قل أفأنبئكم بشر من ذلكم النار وعدها الله الذين كفروا وبئس المصير","aya_tafseer":"[72] وإذا تتلى آيات القرآن الواضحةُ على هؤلاء المشركين ترى الكراهة ظاهرة على وجوههم، يكادون يبطشون بالمؤمنين الذين يدعونهم إلى الله تعالى، ويتلون عليهم آياته. قل لهم -أيها الرسول-: أفلا أخبركم بما هو أشد كراهة إليكم من سماع الحق ورؤية الداعين إليه؟ النار أعدَّها الله للكافرين في الآخرة، وبئس المكان الذي يصيرون إليه."},{"id":"2668","jozz":"17","page":"341","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"1","line_end":"4","aya_no":"73","aya_text":"يَٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٞ فَٱسۡتَمِعُواْ لَهُۥٓۚ إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَن يَخۡلُقُواْ ذُبَابٗا وَلَوِ ٱجۡتَمَعُواْ لَهُۥۖ وَإِن يَسۡلُبۡهُمُ ٱلذُّبَابُ شَيۡـٔٗا لَّا يَسۡتَنقِذُوهُ مِنۡهُۚ ضَعُفَ ٱلطَّالِبُ وَٱلۡمَطۡلُوبُ","aya_text_emlaey":"ياأيها الناس ضرب مثل فاستمعوا له إن الذين تدعون من دون الله لن يخلقوا ذبابا ولو اجتمعوا له وإن يسلبهم الذباب شيئا لا يستنقذوه منه ضعف الطالب والمطلوب","aya_tafseer":"[73] يا أيها الناس ضُرِب مثل فاستمعوا له وتدبروه: إن الأصنام والأنداد التي تعبدونها من دون الله لن تقدر مجتمعة على خَلْق ذبابة واحدة، فكيف بخلق ما هو أكبر؟ ولا تقدر أن تستخلص ما يسلبه الذباب منها، فهل بعد ذلك مِن عَجْز؟ فهما ضعيفان معاً: ضَعُفَ الطالب الذي هو المعبود من دون الله أن يستنقذ ما أخذه الذباب منه، وضَعُفَ المطلوب الذي هو الذباب، فكيف تُتَّخذ هذه الأصنام والأنداد آلهة، وهي بهذا الهوان؟"},{"id":"2669","jozz":"17","page":"341","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"4","line_end":"5","aya_no":"74","aya_text":"مَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ","aya_text_emlaey":"ما قدروا الله حق قدره إن الله لقوي عزيز","aya_tafseer":"[74] هؤلاء المشركون لم يعظِّموا الله حق تعظيمه، إذ جعلوا له شركاء، وهو القوي الذي خلق كل شيء، العزيز الذي لا يغالَب."},{"id":"2670","jozz":"17","page":"341","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"5","line_end":"6","aya_no":"75","aya_text":"ٱللَّهُ يَصۡطَفِي مِنَ ٱلۡمَلَٰٓئِكَةِ رُسُلٗا وَمِنَ ٱلنَّاسِۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٞ","aya_text_emlaey":"الله يصطفي من الملائكة رسلا ومن الناس إن الله سميع بصير","aya_tafseer":"[75] الله سبحانه وتعالى يختار من الملائكة رسلاً إلى أنبيائه، ويختار من الناس رسلاً؛ لتبليغ رسالاته إلى الخلق، إن الله سميع لأقوال عباده، بصير بجميع الأشياء، وبمن يختاره للرسالة من خلقه."},{"id":"2671","jozz":"17","page":"341","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"6","line_end":"7","aya_no":"76","aya_text":"يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ","aya_text_emlaey":"يعلم ما بين أيديهم وما خلفهم وإلى الله ترجع الأمور","aya_tafseer":"[76] وهو سبحانه يعلم ما بين أيدي ملائكته ورسله من قبل أن يخلقهم، ويعلم ما هو كائن بعد فنائهم. وإلى الله وحده ترجع الأمور."},{"id":"2672","jozz":"17","page":"341","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"8","line_end":"9","aya_no":"77","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱرۡكَعُواْ وَٱسۡجُدُواْۤ وَٱعۡبُدُواْ رَبَّكُمۡ وَٱفۡعَلُواْ ٱلۡخَيۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ۩","aya_text_emlaey":"ياأيها الذين آمنوا اركعوا واسجدوا واعبدوا ربكم وافعلوا الخير لعلكم تفلحون","aya_tafseer":"[77] يا أيها الذين آمنوا بالله ورسوله محمد -صلى الله عليه وسلم- اركعوا واسجدوا في صلاتكم، واعبدوا ربكم وحده لا شريك له، وافعلوا الخير؛ لتفلحوا،،"},{"id":"2673","jozz":"17","page":"341","sura_no":"22","sura_name_en":"Al-Ḥajj","sura_name_ar":"الحج ","line_start":"10","line_end":"15","aya_no":"78","aya_text":"وَجَٰهِدُواْ فِي ٱللَّهِ حَقَّ جِهَادِهِۦۚ هُوَ ٱجۡتَبَىٰكُمۡ وَمَا جَعَلَ عَلَيۡكُمۡ فِي ٱلدِّينِ مِنۡ حَرَجٖۚ مِّلَّةَ أَبِيكُمۡ إِبۡرَٰهِيمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِينَ مِن قَبۡلُ وَفِي هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيۡكُمۡ وَتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِۚ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَٱعۡتَصِمُواْ بِٱللَّهِ هُوَ مَوۡلَىٰكُمۡۖ فَنِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ","aya_text_emlaey":"وجاهدوا في الله حق جهاده هو اجتباكم وما جعل عليكم في الدين من حرج ملة أبيكم إبراهيم هو سماكم المسلمين من قبل وفي هذا ليكون الرسول شهيدا عليكم وتكونوا شهداء على الناس فأقيموا الصلاة وآتوا الزكاة واعتصموا بالله هو مولاكم فنعم المولى ونعم النصير","aya_tafseer":"[78] وجاهدوا أنفسكم، وقوموا قياماً تامّاً بأمر الله، وادعوا الخلق إلى سبيله، وجاهدوا بأموالكم وألسنتكم وأنفسكم، مخلصين فيه النية لله عز وجل، مسلمين له قلوبكم وجوارحكم، هو اصطفاكم لحمل هذا الدين، وقد مَنَّ عليكم بأن جعل شريعتكم سمحة، ليس فيها تضييق ولا تشديد في تكاليفها وأحكامها، كما كان في بعض الأمم قبلكم، هذه الملة السمحة هي ملة أبيكم إبراهيم، وقد سَمَّاكم الله المسلمين مِن قبلُ في الكتب المنزلة السابقة، وفي هذا القرآن، وقد اختصَّكم بهذا الاختيار؛ ليكون خاتم الرسل محمد -صلى الله عليه وسلم- شاهداً عليكم بأنه بلَّغكم رسالة ربه، وتكونوا شهداء على الأمم أن رسلهم قد بلَّغتهم بما أخبركم الله به في كتابه، فعليكم أن تعرفوا لهذه النعمة قدرها، فتشكروها، وتحافظوا على معالم دين الله بأداء الصلاة بأركانها وشروطها، وإخراج الزكاة المفروضة، وأن تلجؤوا إلى الله سبحانه وتعالى، وتتوكلوا عليه، فهو نِعْمَ المولى لمن تولاه، ونعم النصير لمن استنصره."}]
